css:
.corpstruct-sim-container {
    padding: 28px 32px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', 'Inter', Helvetica, Arial, sans-serif;
    color: #1a2744;
}
.corpstruct-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2c3e6b 100%);
    color: #ffffff;
    padding: 32px 36px 28px;
    margin-bottom: 24px;
    border-radius: 4px;
    position: relative;
}
.corpstruct-sim-header h1 {
    font-size: 1.5rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: 0.02em;
}
.corpstruct-sim-subtitle {
    font-size: 0.88rem;
    color: #a8b4cc;
    margin: 0;
    font-weight: 400;
}
.corpstruct-sim-header-badge {
    position: absolute;
    top: 16px;
    right: 24px;
    background: #e8c547;
    color: #1a2744;
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    padding: 4px 14px;
    border-radius: 2px;
    text-transform: uppercase;
}
.corpstruct-sim-period-counter {
    text-align: center;
    font-size: 0.85rem;
    color: #5a6678;
    margin-bottom: 20px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    font-weight: 600;
}
.corpstruct-sim-period-counter span#currentDay,
.corpstruct-sim-period-counter span#maxPeriods {
    color: #1a2744;
    font-weight: 700;
    font-size: 1rem;
}
.corpstruct-sim-briefing {
    background: #ffffff;
    border-left: 4px solid #2c3e6b;
    padding: 22px 28px;
    margin-bottom: 24px;
    border-radius: 0 4px 4px 0;
    box-shadow: 0 1px 4px rgba(26,39,68,0.07);
}
.corpstruct-sim-briefing-title {
    font-size: 1.05rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 8px 0;
}
.corpstruct-sim-briefing-text {
    font-size: 0.88rem;
    color: #3d4f6a;
    margin: 0;
    line-height: 1.65;
}
.corpstruct-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 14px;
    margin-bottom: 24px;
}
.corpstruct-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #dee2e8;
    border-radius: 4px;
    padding: 18px 14px;
    text-align: center;
    border-top: 3px solid #dee2e8;
    transition: box-shadow 0.2s ease;
}
.corpstruct-sim-kpi-card:hover {
    box-shadow: 0 2px 8px rgba(26,39,68,0.1);
}
.corpstruct-sim-kpi-cash { border-top-color: #1a6b3c; }
.corpstruct-sim-kpi-compliance { border-top-color: #c0392b; }
.corpstruct-sim-kpi-governance { border-top-color: #2c3e6b; }
.corpstruct-sim-kpi-investor { border-top-color: #e8c547; }
.corpstruct-sim-kpi-flexibility { border-top-color: #2980b9; }
.corpstruct-sim-kpi-label {
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #586576;
    margin-bottom: 8px;
    font-weight: 600;
}
.corpstruct-sim-kpi-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #1a2744;
}
.corpstruct-sim-kpi-cash .corpstruct-sim-kpi-value { color: #1a6b3c; }
.corpstruct-sim-kpi-compliance .corpstruct-sim-kpi-value { color: #c0392b; }
.corpstruct-sim-kpi-governance .corpstruct-sim-kpi-value { color: #2c3e6b; }
.corpstruct-sim-kpi-investor .corpstruct-sim-kpi-value { color: #8a6d00; }
.corpstruct-sim-kpi-flexibility .corpstruct-sim-kpi-value { color: #2471a3; }
.corpstruct-sim-controls {
    background: #ffffff;
    border: 1px solid #dee2e8;
    border-radius: 4px;
    padding: 24px 28px;
    margin-bottom: 24px;
    box-shadow: 0 1px 4px rgba(26,39,68,0.05);
}
.corpstruct-sim-controls h3 {
    font-size: 0.95rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 18px 0;
    padding-bottom: 10px;
    border-bottom: 1px solid #eef0f4;
}
.corpstruct-sim-decision-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 20px;
}
.corpstruct-sim-decision-group label {
    display: block;
    font-size: 0.78rem;
    font-weight: 600;
    color: #5a6678;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 6px;
}
.corpstruct-sim-select {
    width: 100%;
    padding: 10px 14px;
    border: 1px solid #c8ced8;
    border-radius: 3px;
    background: #f8f9fb;
    color: #1a2744;
    font-size: 0.88rem;
    font-family: inherit;
    transition: border-color 0.2s ease;
    appearance: auto;
}
.corpstruct-sim-select:focus {
    outline: none;
    border-color: #2c3e6b;
    background: #ffffff;
    box-shadow: 0 0 0 3px rgba(44,62,107,0.1);
}
.corpstruct-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
}
.corpstruct-sim-btn-primary {
    background: #1a2744;
    color: #ffffff;
    border: none;
    padding: 10px 28px;
    font-size: 0.88rem;
    font-weight: 600;
    border-radius: 3px;
    cursor: pointer;
    transition: background 0.2s ease;
    letter-spacing: 0.02em;
}
.corpstruct-sim-btn-primary:hover {
    background: #2c3e6b;
}
.corpstruct-sim-btn-outline {
    background: transparent;
    color: #5a6678;
    border: 1px solid #c8ced8;
    padding: 8px 18px;
    font-size: 0.82rem;
    font-weight: 500;
    border-radius: 3px;
    cursor: pointer;
    transition: border-color 0.2s ease, color 0.2s ease;
}
.corpstruct-sim-btn-outline:hover {
    border-color: #1a2744;
    color: #1a2744;
}
.corpstruct-sim-history {
    margin-bottom: 24px;
}
.corpstruct-sim-container table {
    width: 100%;
    background: #ffffff;
    border-radius: 4px;
    overflow: hidden;
    border: 1px solid #dee2e8;
    font-size: 0.82rem;
}
.corpstruct-sim-container table thead th {
    background: #1a2744;
    color: #ffffff;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.72rem;
    padding: 10px 14px;
    border: none;
}
.corpstruct-sim-container table tbody td {
    padding: 8px 14px;
    border-bottom: 1px solid #eef0f4;
    color: #3d4f6a;
}
.corpstruct-sim-container table tbody tr:nth-child(even) {
    background: #f8f9fb;
}
.corpstruct-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
}
.corpstruct-sim-chart-box {
    background: #ffffff;
    border: 1px solid #dee2e8;
    border-radius: 4px;
    padding: 18px;
    min-height: 280px;
    position: relative;
}
@media (max-width: 768px) {
    .corpstruct-sim-container { padding: 16px; }
    .corpstruct-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .corpstruct-sim-kpi-grid > :last-child { grid-column: span 2; }
    .corpstruct-sim-decision-row { grid-template-columns: 1fr; }
    .corpstruct-sim-charts { grid-template-columns: 1fr; }
    .corpstruct-sim-header h1 { font-size: 1.2rem; }
    .corpstruct-sim-kpi-value { font-size: 1.3rem; }
}

