                }
            }

            if (period === 2) {
                roundCost += ds.annualCompliance;
                if (d.decision1 === 'conservative') {
                    roundCost += 2000000;
                    govDelta += 5;
                    narrative = t('r2_result_conservative');
                } else if (d.decision1 === 'balanced') {
                    narrative = t('r2_result_balanced');
                } else if (d.decision1 === 'aggressive') {
                    roundCost -= 3000000;
                    govDelta -= 10;
                    // Session-stable audit roll: draw once, reuse thereafter so an
                    // Undo→resubmit cannot reroll the 30% audit risk (fairness/replay).
                    if (this._r2AuditRoll === null) { this._r2AuditRoll = Math.random(); }
                    var penalty = this._r2AuditRoll < 0.3;
                    if (penalty) {
                        roundCost += 10000000;
                        ds.taxPenaltyApplied = true;
                        narrative = t('r2_result_aggressive_penalty');
                    } else {
                        narrative = t('r2_result_aggressive_ok');
                    }
                }
                if (d.decision2 === 'basic') {
                    roundCost += 3000000;
                    invDelta += 20;
                } else if (d.decision2 === 'full') {
                    roundCost += 8000000;
                    invDelta += 40;
                    if (ds.structureType === 'sa') {
                        invDelta += 10;
                    } else {
                        invDelta -= 5;
                    }
                }
            }

            if (period === 3) {
                roundCost += ds.annualCompliance;
                if (d.decision1 === 'assembly_vote') {
                    if (ds.structureType === 'sa') {
                        govDelta += 15;
                        flexDelta -= 10;
                    } else {
                        govDelta += 5;
                        flexDelta -= 5;
                        roundCost += 1000000;
                    }
                    narrative = t('r3_result_assembly');
                } else if (d.decision1 === 'mediation') {
                    govDelta += 10;
                    flexDelta += 5;
                    roundCost += 2000000;
                    narrative = t('r3_result_mediation');
                } else if (d.decision1 === 'partner_buyout') {
                    govDelta += 5;
                    flexDelta += 10;
                    roundCost += 15000000;
                    narrative = t('r3_result_buyout');
                } else if (d.decision1 === 'veto_clause') {
                    govDelta += 10;
                    flexDelta -= 15;
                    roundCost += 500000;
                    narrative = t('r3_result_veto');
                }
                if (d.decision2 === 'enhanced') {
                    govDelta += 10;
                    roundCost += 5000000;
                }
            }

            if (period === 4) {
                roundCost += ds.annualCompliance;
                if (d.decision1 === 'maintain') {
                    flexDelta += 5;
                    narrative = t('r4_result_maintain');
                } else if (d.decision1 === 'convert') {
                    if (ds.structureType === 'sas') {
                        roundCost += 5000000;
                        govDelta += 20;
                        invDelta += 20;
                        flexDelta -= 20;
                        ds.annualCompliance = 15000000;
                        narrative = t('r4_result_convert_to_sa');
                    } else {
                        roundCost += 3000000;
                        govDelta -= 10;
                        invDelta -= 10;
                        flexDelta += 20;
                        ds.annualCompliance = 6000000;
                        narrative = t('r4_result_convert_to_sas');
                    }
                } else if (d.decision1 === 'restructure') {
                    roundCost += 8000000;
                    govDelta += 10;
                    invDelta += 10;
                    flexDelta += 10;
                    narrative = t('r4_result_restructure');
                }
                if (d.decision2 === 'organic') {
                    roundCost += 2000000;
                    govDelta += 5;
                    invDelta += 5;
                    flexDelta += 5;
                } else if (d.decision2 === 'vc_funded') {
                    if (ds.investorReadiness + invDelta >= 60) {
                        // COP $30.000M (30 billion) VC round per Concept §7 / narrative "$30B".
                        ds.cash += 30000000000;
                        invDelta += 15;
                        narrative += '<br>' + t('r4_vc_success');
                    } else {
                        roundCost += 3000000;
                        narrative += '<br>' + t('r4_vc_fail');
                    }
                } else if (d.decision2 === 'acquisition') {
                    if (ds.governance + govDelta >= 70) {
                        // COP $80.000M (80 billion) enterprise value per Concept §7 / narrative "$80B".
                        ds.cash += 80000000000;
                        govDelta += 10;
                        narrative += '<br>' + t('r4_acq_success');
                    } else {
                        roundCost += 5000000;
                        narrative += '<br>' + t('r4_acq_fail');
                    }
                }
            }

            ds.cash -= roundCost;
            ds.governance = Math.max(0, Math.min(100, ds.governance + govDelta));
            ds.investorReadiness = Math.max(0, Math.min(100, ds.investorReadiness + invDelta));
            ds.flexibility = Math.max(0, Math.min(100, ds.flexibility + flexDelta));

            ds.cashHistory.push(ds.cash);
            ds.governanceHistory.push(ds.governance);
            ds.investorHistory.push(ds.investorReadiness);
            ds.flexibilityHistory.push(ds.flexibility);
            ds.roundCostHistory.push(roundCost);

            // Platform score: same composite getPerformanceSummary computes (governance, investor
            // readiness and flexibility averaged, already 0-100), capped just under a tier when its
            // cash gate fails, same as the verdict falling through to the weaker tier below it.
            var overallScore = Math.max(0, Math.min(100, Math.round((ds.governance + ds.investorReadiness + ds.flexibility) / 3)));
            if (overallScore >= 70 && !(ds.cash > 30000000)) overallScore = 69;
            if (overallScore >= 50 && !(ds.cash > 10000000)) overallScore = 49;
            overallScore = Math.max(0, Math.min(100, overallScore));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            // Advance the briefing/decision panel to the NEXT round.
            // NOTE: `period` is captured above BEFORE the framework increments
            // state.currentPeriod, so nextPeriod is exactly period+1. (The prior
            // code read `state.currentPeriod + 1` inside the timeout, which fires
            // AFTER the increment and therefore skipped a round — off-by-one.)
            var self = this;
            var nextPeriod = period + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: period,
                decision1: d.decision1,
                decision2: d.decision2,
                roundCost: roundCost,
                governance: ds.governance,
                investorReadiness: ds.investorReadiness,
                flexibility: ds.flexibility,
                cash: ds.cash,
                narrative: narrative
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod',
                function(v) { return Math.min(v, 4); });   // defensive: never render "5 of 4"
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('complianceDisplay', 'domainState.annualCompliance',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('governanceDisplay', 'domainState.governance',
                function(v) { return v + '/100'; });
            uiManager.bind('investorDisplay', 'domainState.investorReadiness',
                function(v) { return v + '/100'; });
            uiManager.bind('flexibilityDisplay', 'domainState.flexibility',
                function(v) { return v + '/100'; });
            // Accessibility: give the two canvases a localized text alternative.
            var t = window.mySimulation.t.bind(window.mySimulation);
            var cc = document.getElementById('cashChart');
            if (cc) { cc.setAttribute('role', 'img'); cc.setAttribute('aria-label', t('chart_cash_aria')); }
            var mc = document.getElementById('metricsChart');
            if (mc) { mc.setAttribute('role', 'img'); mc.setAttribute('aria-label', t('chart_metrics_aria')); }
        }

        _fmtCurrency(v) {
            var a = Math.abs(v);
            if (a >= 1000000000) { return '$' + (v / 1000000000).toFixed(a >= 10000000000 ? 0 : 1) + 'B'; }
            if (a >= 1000000)    { return '$' + (v / 1000000).toFixed(0) + 'M'; }
            return '$' + Math.round(v).toLocaleString();
        }

